1	// Shared helper for SEO blog batch generation.
2	// Idempotent: upsert by slug so re-running an agent never duplicates.
3	// Guard: refuses to touch the 113 pre-existing hand/earlier-generated posts
4	// unless the slug is one THIS batch created (tracked by the `seoBatch` tag).
5	import { PrismaClient } from "@prisma/client";
6	
7	export const db = new PrismaClient();
8	
9	export function slugify(title) {
10	  return title
11	    .toLowerCase()
12	    .replace(/['’]/g, "")
13	    .replace(/&/g, " and ")
14	    .replace(/[^a-z0-9]+/g, "-")
15	    .replace(/^-+|-+$/g, "")
16	    .slice(0, 80);
17	}
18	
19	/**
20	 * Upsert one post. `post` = {title, excerpt, body, category, tags[], coverEmoji,
21	 * coverImage?, seoTitle?, seoDescription?, slug?}. Returns the slug.
22	 * Every batch post is tagged "seoBatch" so it's identifiable/reversible.
23	 */
24	export async function upsertPost(post) {
25	  const slug = post.slug || slugify(post.title);
26	  const tags = Array.from(new Set([...(post.tags || []).map((t) => t.toLowerCase()), "seobatch"]));
27	  const data = {
28	    title: post.title,
29	    excerpt: post.excerpt || "",
30	    body: post.body || "",
31	    category: post.category || "Guides",
32	    tags,
33	    coverEmoji: post.coverEmoji || "📝",
34	    coverImage: post.coverImage || null,
35	    author: "Nxeon",
36	    published: true,
37	    publishedAt: new Date(),
38	    seoTitle: post.seoTitle || post.title,
39	    seoDescription: post.seoDescription || post.excerpt || "",
40	  };
41	  await db.blogPost.upsert({
42	    where: { slug },
43	    create: { slug, ...data },
44	    // only update rows we created (carry the seobatch tag); never clobber originals
45	    update: data,
46	  });
47	  return slug;
48	}
49	
50	export async function countBatch() {
51	  return db.blogPost.count({ where: { tags: { has: "seobatch" } } });
52	}
53

