];
let warn=0;
for (const s of slugs){
  const p = await db.blogPost.findUnique({where:{slug:s}});
  if(!p){console.log("MISSING",s);warn++;continue;}
  const words = p.body.trim().split(/\s+/).length;
  const shots = (p.body.match(/{{SCREENSHOT}}/g)||[]).length;
  const links = (p.body.match(/\]\(\//g)||[]).length;
  const faq = /## FAQ/.test(p.body);
  const st = p.seoTitle.length, sd = p.seoDescription.length;
  const flags=[];
  if(words<1000||words>1650) flags.push("WORDS="+words);
  if(shots<1||shots>2) flags.push("SHOTS="+shots);
  if(links<3) flags.push("LINKS="+links);
  if(!faq) flags.push("NOFAQ");
  if(st>60) flags.push("SEOTITLE="+st);
  if(sd>155) flags.push("SEODESC="+sd);
  console.log((flags.length?"⚠ ":"ok "), s.padEnd(52), "w="+words, "shot="+shots, "links="+links, "st="+st, "sd="+sd, flags.join(","));
  if(flags.length)warn++;
}
console.log("\nTotal seobatch posts in DB:", await db.blogPost.count({where:{tags:{has:"seobatch"}}}));
console.log("Warnings:", warn);
await db.$disconnect();
